#!/usr/bin/env bash
# Roll back this additive update without restoring/replacing the live database.
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
umask 077
readonly STATE_FILE="${AETHER_MANAGEMENT_UPDATE_STATE:-/root/aether-management-groups-last-success.env}"
log() { printf '[%s] %s\n' "$(date '+%F %T')" "$*"; }
[[ "$(id -u)" == 0 && -f "${STATE_FILE}" && ! -L "${STATE_FILE}" ]]
[[ "$(stat -c '%u:%a' "${STATE_FILE}")" == '0:600' ]]
exec 9>/run/lock/aether-cm-install.lock
flock -n 9
# State is root-owned and generated by the installer; contains no credentials.
# shellcheck disable=SC1090
source "${STATE_FILE}"
[[ -d "${PREVIOUS_RELEASE}" && "$(readlink -f "${INSTALL_ROOT}/current")" == "${NEW_RELEASE}" ]]
[[ "${MIGRATION_CHECKSUM}" =~ ^[0-9a-f]+$ ]]
set -a
# shellcheck disable=SC1090
source "${ENV_FILE}"
set +a
DATABASE_CONNECTION="${AETHER_DATABASE_URL:-${AETHER_GATEWAY_DATA_POSTGRES_URL:-${DATABASE_URL:-}}}"
CONNECTION_FILE="$(mktemp /root/.aether-rollback-db.XXXXXX)"
trap 'rm -f -- "${CONNECTION_FILE}"' EXIT
AETHER_DEPLOY_DATABASE_CONNECTION="${DATABASE_CONNECTION}" python3 "${BACKUP}/prepare-deploy-postgres.py" "${CONNECTION_FILE}"
psql_app() { PGSERVICEFILE="${CONNECTION_FILE}" PGSERVICE=aether_management_update psql --dbname='service=aether_management_update' -X -v ON_ERROR_STOP=1 "$@"; }
ledger() { psql_app -Atqc "SELECT version, encode(checksum, 'hex'), success FROM public._sqlx_migrations ORDER BY version"; }
health() {
  curl -fsS --max-time 5 "http://127.0.0.1:${APP_PORT:-8084}/health" >/dev/null 2>&1 &&
    curl -fsS --max-time 5 "http://127.0.0.1:${APP_PORT:-8084}/readyz" >/dev/null 2>&1
}
# Exact ledger comparison includes failed migrations and all old checksums.
ledger > "${BACKUP}/ledger.rollback-check"
cmp "${BACKUP}/ledger.after" "${BACKUP}/ledger.rollback-check"
[[ "$(psql_app -Atqc "SELECT encode(checksum, 'hex') FROM public._sqlx_migrations WHERE version=20261115000000 AND success")" == "${MIGRATION_CHECKSUM}" ]]
CUTOVER=0
recover_new() {
  local rc="$1"
  trap - ERR INT TERM
  if (( CUTOVER )); then
    log 'Rollback failed; recovering the current release and its migration ledger'
    systemctl stop "${SERVICE}" || true
    if ! psql_app -v record="$(< "${BACKUP}/migration.record.json")" <<'SQL'
INSERT INTO public._sqlx_migrations
SELECT (json_populate_record(NULL::public._sqlx_migrations, :'record'::json)).*
ON CONFLICT (version) DO NOTHING;
SQL
    then
      log 'CRITICAL: could not recover migration ledger; service remains stopped'
      exit 1
    fi
    if ! ledger > "${BACKUP}/ledger.recovered" || ! cmp "${BACKUP}/ledger.after" "${BACKUP}/ledger.recovered"; then
      log 'CRITICAL: recovered migration ledger does not match; service remains stopped'
      exit 1
    fi
    local link="${INSTALL_ROOT}/.recover-$(date +%s)-$$"
    if ! ln -s "${NEW_RELEASE}" "${link}" || ! mv -Tf "${link}" "${INSTALL_ROOT}/current"; then
      log 'CRITICAL: could not recover current release link; service remains stopped'
      exit 1
    fi
    systemctl start "${SERVICE}" || true
    for _ in $(seq 1 90); do
      if health; then log 'Current release recovered; rollback was not applied'; exit "${rc}"; fi
      sleep 2
    done
    log 'CRITICAL: current release recovery health check failed'
  fi
  exit "${rc}"
}
trap 'recover_new "$?"' ERR
trap 'recover_new 130' INT TERM
log 'Stopping Aether and reverting only this additive migration ledger entry'
CUTOVER=1
systemctl stop "${SERVICE}"
[[ "$(systemctl is-active "${SERVICE}" || true)" != active ]]
# Keep the independent management config and all post-deployment business writes.
REMOVED="$(psql_app -Atqc "WITH removed AS (DELETE FROM public._sqlx_migrations WHERE version=20261115000000 AND encode(checksum, 'hex')='${MIGRATION_CHECKSUM}' RETURNING version) SELECT count(*) FROM removed")"
[[ "${REMOVED}" == 1 ]]
ledger > "${BACKUP}/ledger.rolled-back"
cmp "${BACKUP}/ledger.before" "${BACKUP}/ledger.rolled-back"
LINK="${INSTALL_ROOT}/.rollback-$(date +%s)-$$"
ln -s "${PREVIOUS_RELEASE}" "${LINK}"
mv -Tf "${LINK}" "${INSTALL_ROOT}/current"
systemctl start "${SERVICE}"
HEALTHY=0
for _ in $(seq 1 90); do
  if health; then HEALTHY=1; break; fi
  sleep 2
done
[[ "${HEALTHY}" == 1 ]]
CUTOVER=0
trap - ERR INT TERM
log "Previous release restored; live database retained: ${PREVIOUS_RELEASE}"
